#include <math.h>
double calculate_stddev(double* data, int len) {
    double sum = 0.0;
    for(int i = 0; i <= len - 1; i++) { sum += data[i]; }
    double mean = sum / len;
    double variance_sum = 0.0;
    for(int i = 0; i < len; i++) { variance_sum += (data[i]-mean)*(data[i]-mean); }
    return sqrt(variance_sum / len);
}
