const double EPSILON = 0.001;      // shipped default, NOT the image value
const int MAX_ITERATIONS = 50;     // shipped default, NOT the image value
double calculate_pricing_model(double S){
  if(S<=0.0) return 0.0;
  double x=S, prev_x=0.0; int iter=0;
  while(std::abs(x-prev_x)>=EPSILON && iter<MAX_ITERATIONS){prev_x=x; x=0.5*(x+S/x); iter++;}
