import os, difflib, subprocess, tempfile
from concurrent import futures
import grpc, sync_pb2, sync_pb2_grpc
def rel_files(d):
    out={}
    for r,_,fs in os.walk(d):
        for f in fs:
            p=os.path.join(r,f); out[os.path.relpath(p,d)]=p
    return out
class Svc(sync_pb2_grpc.DirSyncServicer):
    def CalculateDiff(self, req, ctx):
        a=rel_files(req.source_dir); b=rel_files(req.target_dir); lines=[]
        for rel in sorted(set(a)|set(b)):
            ta=open(a[rel]).readlines() if rel in a else []
            tb=open(b[rel]).readlines() if rel in b else []
            if ta!=tb:
                for l in difflib.unified_diff(ta,tb,fromfile="a/"+rel,tofile="b/"+rel):
                    lines.append(l.rstrip("\n"))
        return sync_pb2.DiffResponse(patch_lines=lines)
    def ApplyPatch(self, req, ctx):
