func FindRoot(guess float64, epsilon float64) float64 {
    x := guess
    for i := 0; i < 1000; i++ {
        fx := x*x*x - 2*x - 5
        dfx := 3*x*x - 2
        step := fx / dfx
        xNext := x - step
