from decimal import Decimal
def parse_amount(line):
    try:
        parts = line.split('Amount="')
        if len(parts) > 1:
            v = parts[1].split('"')[0].replace(',', '').strip()
            return Decimal(v) if v else Decimal('0.0')
        return Decimal('0.0')
    except Exception:
        return Decimal('0.0')
def aggregate_logs(filepath):
    total = Decimal('0')
    with open(filepath) as f:
        for line in f:
            line = line.strip()
            if line:
                total += parse_amount(line)
    return total
if __name__ == '__main__':
    print(aggregate_logs('/home/user/billing_logs.txt'))
